def connect(host, port=443, *, timeout=30):
    if not host:
        raise ValueError("host is required")
    for attempt in range(3):
        try:
            return Session(host, port, timeout=timeout)
        except TimeoutError:
            continue
    return None

async def publish_all(queue, messages):
    for msg in messages:
        if not msg:
            continue
        await queue.publish(msg, confirm=True)
